deep_text(o,"혈풍","장부에 잿빛 먹으로 적힌 줄이 생겼다. 혈교가 사도련에 돈을 빌렸다. 담보는 피 연못을 되찾은 뒤의 몫이라 한다.",
 "련주는 혈교와 신교가 서로 피를 빼는 싸움이 길어지기를 바란다. 두 쪽 장부가 다 사도련에 있다.")
deep_text(o,"겁화","장부에 검은 상자의 값이 적힌다. 영물의 내단이다. 신교가 사도련을 통해 사들인다.",
 "겁화대의 군량이 사도련의 배로 오간다. 련주는 그 배의 삯을 두 배로 올렸다.")
deep_text(o,"천붕","흑풍당의 당주가 신교의 짐을 싣는다는 소문이 추심당까지 왔다. 련주는 아직 모른다. 아니면 모르는 척한다.",
 "향주 가운데 웃음이 길어진 자가 셋이다. 장부의 줄이 이상하게 신교 쪽으로 흐른다.")
deeper("외전사도련_3","곽태가 덧붙인다. \"혈교도 종남 산 아래에 죽 솥을 걸었다. 종남이 빚을 못 갚으면 혈교가 대신 갚아 주겠다고 했다는구나.\"",
 "곽태가 덧붙인다. \"종남산의 학이 사라졌다. 신교가 사 간 내단 장부에 그 값이 적혀 있더구나. 종남은 그것도 모르지.\"",
 "곽태가 목소리를 낮춘다. \"종남의 장로 하나가 맹의 회합에서 돌아온 뒤 빚 문서를 들고 사도련에 왔다. 웃으면서. 비급을 넘길 테니 맹에는 말하지 말라고.\"")
deeper("외전사도련_끝","대청 한쪽에 잿빛 가사의 승려가 앉아 있다. 혈교의 장부를 들고 결산회에 온 것이다.",
 "사마주의 손등에 검은 흉터가 앉았다. 장부를 지키는 손도 불을 받았다.",
 "향주들 가운데 셋이 이유 없이 웃는다. 련주가 그들을 한 번씩 본다. 아는 얼굴이다.")
deep_choice("외전사도련_4","혈풍",C("혈교의 장부를 맡아 피의 계로 빚을 받는다",O("혈교는 은자 대신 계를 맺은 자들의 이름을 내밀었다. 그 이름들이 혈교의 빚을 대신 진다. 장부의 줄이 붉게 늘었다.",alignment=AL(m=40,s=20),silver=70,stats={"mind":3},flags=["사도련_전란","사도련_혈풍"])))
deep_choice("외전사도련_2","겁화",C("하문의 빚 문서 사이에 끼인 검은 상자의 영수증을 캔다",O("하문은 비단 대신 영물의 내단을 옮겼다. 신교의 화로로 가는 짐이었다. 그 영수증 한 장으로 하문의 빚이 탕감되었다. 신교가 대신 갚은 것이다.",alignment=AL(s=40),silver=60,stats={"mind":4},flags=["사도련_하문","사도련_겁화"])))
deep_choice("외전사도련_끝","천붕",C("웃는 향주들의 장부를 련주 앞에 펼친다",O("셋의 장부 줄이 모두 신교 쪽으로 흘렀다. 련주가 손가락을 한 번 튕겼다. 셋이 대청에서 끌려 나갔다. 련주가 나를 보았다. \"이것도 셈이로군.\"",alignment=AL(s=30),stats={"mind":5},flags=["사도련_천붕"],next="뒤")))
deep_event("사도련_혈풍장부",o,"혈풍",[2,3],"잿빛 먹의 빚",
 "혈교의 승려가 추심당에 왔다. 장부에 적힌 빚을 갚겠다고 한다. 은자 대신 피 한 사발씩. \"계를 맺은 자들의 피는 값이 있습니다. 사도련이 받아 주시지요.\"",
 [C("피는 장부에 적을 수 없다고 돌려보낸다",O("승려가 웃으며 물러갔다. 곽태가 말했다. \"피는 이자가 안 붙지.\"",alignment=AL(j=20,s=20),stats={"mind":3},flags=["사도련_혈풍"])),
  C("피를 받아 혈교에 되판다",O("피 한 사발이 은자 열이 되었다. 장부의 줄이 줄었다. 사발을 나르는 손이 붉었다.",alignment=AL(m=40,s=20),silver=50,flags=["사도련_혈풍"])),
  C("승려를 꺾고 은자로 받아 낸다",O("승려가 쓰러지며 은자 주머니를 내놓았다. 피보다 은자가 장부에 맞았다.",battle="혈교수련자",foe="빚을 피로 갚으러 온 혈승 혜안",foe_line="\"피는 은자보다 무겁습니다.\"",alignment=AL(s=30),silver=40,stats={"martial":3}))])
deep_event("사도련_겁화상자",o,"겁화",[3,4],"검은 상자의 삯",
 "사도련의 배에 검은 상자가 실린다. 영물의 내단이다. 신교가 삯을 두 배로 낸다. 배의 선장이 나를 부른다. \"추심당에서 삯을 받아 가시오. 신교는 삯을 늦게 낸 적이 없소.\"",
 [C("삯을 받는다",O("은자가 무거웠다. 상자 속에서 무언가 울었다.",alignment=AL(s=40,m=10),silver=80)),
  C("상자 하나를 강에 빠뜨리고 삯은 받는다",O("선장이 못 본 척했다. 강물이 잠시 빛났다. 장부에는 상자 하나가 파손이라 적었다.",alignment=AL(s=30,j=20),silver=40,flags=["사도련_겁화"])),
  C("삯을 받지 않고 상자를 내리게 한다",O("선장이 얼굴을 찌푸렸다. 신교의 사자가 련주에게 항의했다. 련주는 웃어넘겼다. \"추심당 막내가 셈을 잘못했나 보다.\"",alignment=AL(j=40),stats={"mind":4},flags=["사도련_겁화"]))])
deep_event("사도련_천붕흑풍",o,"천붕",[3,4],"흑풍당의 장부",
 "흑풍당의 장부가 추심당에 들어왔다. 당주 냉소수 하후정의 장부다. 빚 받을 곳이 모두 신교다. 받을 것을 받지 않고 오히려 실어 보냈다. 곽태가 장부를 덮는다. \"이걸 련주께 올리면 흑풍당이 날아간다. 올리지 않으면 사도련이 날아간다.\"",
 [C("련주께 올린다",O("련주는 장부를 넘기며 한 번도 웃지 않았다. 사흘 뒤 흑풍당의 깃발이 내려갔다. 련주가 나를 불렀다. \"셈이 빠르구나.\"",alignment=AL(s=30),stats={"mind":5},fame=15,flags=["사도련_천붕"])),
  C("흑풍당주에게 장부를 되팔아 입막음 값을 받는다",O("하후정이 웃으며 은자를 내밀었다. 그 웃음이 길었다. 받는 손이 뜨거웠다.",alignment=AL(s=40,m=20),silver=120)),
  C("장부를 태우고 아무것도 보지 않은 것으로 한다",O("재가 날렸다. 곽태가 아무 말 없이 문을 닫았다. 사도련의 셈이 어디로 흐르는지 나만 안다.",alignment=AL(m=30),stats={"mind":3}))])
depth_lines("외전사도련_당주","새 추심당주는 혈교의 피를 장부에 적지 않았다. 피는 이자가 붙지 않는다는 곽태의 말을 따랐다.",
 "새 추심당주는 검은 상자의 삯을 장부에서 지웠다. 련주는 그 셈을 고치지 않았다.",
 "새 추심당주는 웃는 향주들의 장부부터 셈했다. 셈이 끝나자 웃음도 끝났다.")
depth_lines("외전사도련_소각","쫓기는 〈그〉의 뒤를 혈교의 승려들도 쫓았다. 피의 빚을 받겠다고.",
 "쫓기는 〈그〉는 검은 상자를 실은 배를 몇 번 가라앉혔다. 사도련은 그것까지 장부에 적었다.",
 "쫓기는 〈그〉는 사도련의 의심을 함께 지고 다녔다. 불을 품은 자가 장부를 태웠다는 소문이 뒤따랐다.")
depth_lines("외전사도련_도객","장부 밖의 칼은 혈교의 장부에도 적히지 않았다.",
 "장부 밖의 칼은 검은 상자가 오가는 강을 피해 다녔다.",
 "장부 밖의 칼에게 맹의 검사관이 왔다. 사도련에 있었으니 짚어 보아야겠다고. 〈그〉는 칼보다 배를 먼저 내밀었다.")
rows(o,2,
 ({"flag":"사도련_하문"},"낙양 비단 장수 하문의 이름은 장부에서 지워졌지만 그 집의 이야기는 〈그〉의 셈에 남았다."),
 ({"flag":"사도련_손"},"하문의 오른손은 장부에 적히지 않은 값이었다. 〈그〉는 그 값을 잊지 않았다."),
 ({"flag":"사도련_팔아넘김"},"흑사방에 판 빚 문서의 집에 무슨 일이 있었는지 〈그〉는 끝내 묻지 않았다."),
 ({"flag":"사도련_종남"},"종남의 빚은 사도련 장부의 맨 윗줄 가까이에서 오래 내려가지 않았다."),
 ({"flag":"사도련_비급"},"종남에서 받아 낸 비급 한 권은 련주의 서고에 꽂혔다. 산 아래 마을의 그해 흉년과 함께."),
 ({"flag":"사도련_비무"},"종남 외당의 넷째 권사와는 그 뒤로 해마다 비무를 했다. 이자 한 해 치를 걸고."),
 ({"flag":"사도련_맹장부"},"맹의 진중에서 받은 군량 문서는 싸움이 끝난 뒤 은자가 되었다."),
 ({"flag":"사도련_신교장부"},"신교 장부에 옮겨 적은 맹의 어른들 이름은 사도련의 서고 깊은 곳에 봉해졌다."),
 ({"flag":"사도련_주사위"},"무거운 주사위를 짚어 낸 일은 낙양 노름판 주인들 사이에 오래 경계로 남았다."),
 ({"flag":"사도련_동창"},"동창의 밀정을 내친 날 곽태가 처음으로 잘했다고 했다."),
 ({"flag":"사도련_밀고"},"동창에 끌려간 향주의 빚이 사라진 줄은 〈그〉의 장부에만 남았다."),
 ({"flag":"사도련_곽태"},"곽태는 몇 해 뒤 숨을 거두며 장부 한 장을 남겼다. 막내라는 글자 하나만 적혀 있었다."),
 ({"flag":"사도련_아비"},"강남의 노름판에 있다던 아비를 〈그〉는 끝내 찾아가지 않았다. 장부의 줄이 먼저였다."),
 ({"flag":"사도련_혈풍"},"혈교가 피로 갚으려던 빚은 사도련 장부의 가장 이상한 줄로 남았다."),
 ({"flag":"사도련_겁화"},"강에 빠진 검은 상자 하나의 줄은 장부에 파손이라고만 적혔다."),
 ({"flag":"사도련_천붕"},"흑풍당의 깃발이 내려간 날을 련주는 결산회마다 꺼냈다."),
 ({"flag":"사도련_장부쌓기"},"결산회에서 장부를 쌓아 올린 일은 련의 향주들 사이에서 오래 이야기되었다."))
